// coerceValue converts a single AST Value node into a Go value.
func (e *executor) coerceValue(val Value) any {
	switch v := val.(type) {
	case *StringValue:
		return v.V
	case *IntValue:
		return v.V
	case *FloatValue:
		return v.V
	case *BoolValue:
		return v.V
	case *NullValue:
		return nil
	case *EnumValue:
		return v.V
	case *VariableValue:
		return e.variables[v.Name]
	case *ListValue:
		list := make([]any, len(v.Values))
		for i, elem := range v.Values {
			list[i] = e.coerceValue(elem)
		}
		return list
	case *ObjectValue:
		obj := make(map[string]any, len(v.Fields))
		for _, f := range v.Fields {
			obj[f.Name] = e.coerceValue(f.Value)
		}
		return obj
	default:
		return nil
	}
}

